 CREATE OR REPLACE FUNCTION public.placementchildhistorylist(v_cjamspid bigint, v_lipagenumber bigint, v_lipagesize bigint)                                                                                                                                                                                                                                                                                                                                                              
  RETURNS TABLE(totalcount bigint, clientid bigint, clientname character varying, dob timestamp without time zone, gender character varying, placement_id bigint, provider_id integer, servicerequestnumber character varying, intakeserviceid uuid, referalstartdate date, referalstarttime character varying, providername character varying, payment_header_id integer, childreremovaldate date, childreremovaltime character varying, provider_parent_id integer, removal_id integer)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_pagenumber := v_liPageNumber - 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 v_pageoffset := v_pagenumber * v_liPageSize;                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         return query                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         SELECT COUNT(1) OVER() totalcount,                                                                                                                                                                                                                                                                                                                                                                                                                                              
         P.cjamspid as clientid,                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         CAST(INITCAP(TRIM(P.firstname)||' '||TRIM(P.lastname) ||                                                                                                                                                                                                                                                                                                                                                                                                                        
         CASE WHEN P.middlename IS NOT NULL AND TRIM(P.middlename) != '' THEN ', ' || TRIM(P.middlename) ELSE '' END)as  character varying),                                                                                                                                                                                                                                                                                                                                             
         P.dob,GT.typedescription ,TBPM.placement_id,                                                                                                                                                                                                                                                                                                                                                                                                                                    
         TBPM.provider_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         ISR.servicerequestnumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         ISR.intakeserviceid,                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         TBPMP.entry_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         TBPMP.entry_tm ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         (CASE WHEN TBP.provider_nm !='' THEN TBP.provider_nm                                                                                                                                                                                                                                                                                                                                                                                                                            
         WHEN TBP.provider_nm is null THEN (CAST(INITCAP(TRIM(TBP.provider_first_nm)||' '||TRIM(TBP.provider_last_nm) || CASE WHEN TBP.provider_middle_nm IS NOT NULL AND                                                                                                                                                                                                                                                                                                                
         TRIM(TBP.provider_middle_nm) != '' THEN ', ' || TRIM(TBP.provider_middle_nm)ELSE '' END)as  character varying)) ELSE TBP.provider_nm  END) as providername,                                                                                                                                                                                                                                                                                                                     
         TBPM.payment_header_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         TBR.removal_dt,TBR.removal_tm,TBP.affiliate_provider_id,TBR.removal_id                                                                                                                                                                                                                                                                                                                                                                                                          
         FROM person as P                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         JOIN gendertype as GT                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             ON GT.gendertypekey = p.gendertypekey and GT.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                  
         JOIN tb_placement as TBPM                                                                                                                                                                                                                                                                                                                                                                                                                                                       
             ON TBPM.client_id = P.cjamspid and TBPM.delete_sw = 'N'                                                                                                                                                                                                                                                                                                                                                                                                                     
         JOIN tb_placement_providers as TBPMP                                                                                                                                                                                                                                                                                                                                                                                                                                            
              ON TBPMP.placement_id = TBPM.placement_id and TBPMP.delete_sw = 'N'                                                                                                                                                                                                                                                                                                                                                                                                        
         JOIN tb_provider as TBP                                                                                                                                                                                                                                                                                                                                                                                                                                                         
              ON TBP.provider_id = TBPM.provider_id and TBP.delete_sw = 'N'                                                                                                                                                                                                                                                                                                                                                                                                              
         JOIN intakeservicerequest as ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                
              ON ISR.servicerequestnumber = TBPM.case_id::character varying and ISR.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                         
         LEFT JOIN tb_removal as TBR                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                   ON TBR.client_id = P.cjamspid and TBR.delete_sw = 'N'                                                                                                                                                                                                                                                                                                                                                                                                                 
         Where P.cjamspid =  v_cjamspid                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         LIMIT v_liPageSize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                              

